package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.util.*;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.port.DevicePushTokenRepositoryPort;import com.yeyamo_mobile.api.notification_service.domain.DevicePushToken;
@Component public class JpaDevicePushTokenAdapter implements DevicePushTokenRepositoryPort{private final SpringDevicePushTokenRepository repo;public JpaDevicePushTokenAdapter(SpringDevicePushTokenRepository r){repo=r;}public DevicePushToken save(DevicePushToken d){DevicePushTokenEntity e=repo.findById(d.id()).orElseGet(DevicePushTokenEntity::new);e.id=d.id();e.userId=d.userId();e.token=d.token();e.platform=d.platform();e.deviceId=d.deviceId();e.appVersion=d.appVersion();e.enabled=d.enabled();e.createdAt=d.createdAt();e.updatedAt=d.updatedAt();e.lastSeenAt=d.lastSeenAt();e.invalidatedAt=d.invalidatedAt();return domain(repo.save(e));}public Optional<DevicePushToken>findById(UUID id){return repo.findById(id).map(this::domain);}public Optional<DevicePushToken>findByUserIdAndDeviceId(String u,String d){return repo.findByUserIdAndDeviceId(u,d).map(this::domain);}public Optional<DevicePushToken>findByToken(String t){return repo.findByToken(t).map(this::domain);}public List<DevicePushToken>findEnabledByUserId(String u){return repo.findByUserIdAndEnabledTrue(u).stream().map(this::domain).toList();}private DevicePushToken domain(DevicePushTokenEntity e){return new DevicePushToken(e.id,e.userId,e.token,e.platform,e.deviceId,e.appVersion,e.enabled,e.createdAt,e.updatedAt,e.lastSeenAt,e.invalidatedAt);}}
